gcAz(){return"\u06a9\u062f \u062a\u0623\u06cc\u06cc\u062f \u062f\u0631 \u062f\u0633\u062a\u0631\u0633 \u0646\u06cc\u0633\u062a."},
gcAq(){return"\u062f\u0631 \u062d\u0627\u0644 \u062d\u0630\u0641 \u0633\u0627\u0644 \u0645\u0627\u0644\u06cc \u062c\u0627\u0631\u06cc\u2026"},
gcAv(){return"\u0628\u0627 \u0645\u0648\u0641\u0642\u06cc\u062a \u0627\u0646\u062c\u0627\u0645 \u0634\u062f"},
gcAA(){return"\u0627\u06cc\u0646 \u0639\u0645\u0644\u06cc\u0627\u062a \u062a\u0645\u0627\u0645 \u0627\u0633\u0646\u0627\u062f \u0633\u0627\u0644 \u0645\u0627\u0644\u06cc \u062c\u0627\u0631\u06cc \u0631\u0627 \u062d\u0630\u0641 \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0633\u0627\u0644 \u0642\u0628\u0644 \u0631\u0627 \u062f\u0648\u0628\u0627\u0631\u0647 \xab\u062c\u0627\u0631\u06cc\xbb \u0645\u06cc\u200c\u06a9\u0646\u062f."},
gcAh(){return"\u0633\u0627\u0644 \u062c\u0627\u0631\u06cc (\u062d\u0630\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f)"},
bm3(a){return"\u0634\u0646\u0627\u0633\u0647 "+a},
gcAn(){return"\u0633\u0627\u0644 \u0628\u0639\u062f\u06cc \u062c\u0627\u0631\u06cc"},
